// Command gen converts the vendored per-version opcode data
// (internal/hermes/opcodes/data/hbcNN.json, built by data/build_data.py)
// into the generated Go tables in internal/hermes/opcodes/hbcNN.
//
// Run it from the internal/hermes/opcodes directory (or via
// `go generate ./...` from the repository root):
//
//	go run ./gen
//
// The generated files are committed; the package is not built as part of
// the normal `go build ./...` dependency graph because nothing imports a
// main package.
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/destruct/destruct/internal/hermes/opcodes"
)

type dataFile struct {
	Version      uint32      `json:"version"`
	Source       string      `json:"source"`
	Instructions []dataInstr `json:"instructions"`
	Builtins     []string    `json:"builtins"`
}

type dataInstr struct {
	Name      string        `json:"name"`
	Opcode    int           `json:"opcode"`
	Operands  []dataOperand `json:"operands"`
	RetTarget bool          `json:"retTarget"`
	Corrected bool          `json:"corrected"`
}

type dataOperand struct {
	Type    string `json:"type"`
	Meaning string `json:"meaning"`
}

func main() {
	dataDir := flag.String("data", "data", "directory holding hbcNN.json files")
	outDir := flag.String("out", ".", "directory to write hbcNN/opcodes.go into")
	flag.Parse()

	if err := run(*dataDir, *outDir); err != nil {
		fmt.Fprintln(os.Stderr, "opcodes/gen:", err)
		os.Exit(1)
	}
}

func run(dataDir, outDir string) error {
	entries, err := os.ReadDir(dataDir)
	if err != nil {
		return fmt.Errorf("reading %s: %w", dataDir, err)
	}

	var versions []uint32
	for _, e := range entries {
		name := e.Name()
		if !strings.HasPrefix(name, "hbc") || !strings.HasSuffix(name, ".json") {
			continue
		}
		v, err := strconv.ParseUint(strings.TrimSuffix(strings.TrimPrefix(name, "hbc"), ".json"), 10, 32)
		if err != nil {
			return fmt.Errorf("bad data file name %q: %w", name, err)
		}
		versions = append(versions, uint32(v))
	}
	if len(versions) == 0 {
		return fmt.Errorf("no hbcNN.json files in %s", dataDir)
	}
	sort.Slice(versions, func(i, j int) bool { return versions[i] < versions[j] })

	for _, version := range versions {
		src := filepath.Join(dataDir, fmt.Sprintf("hbc%d.json", version))
		if err := generateOne(src, outDir, version); err != nil {
			return fmt.Errorf("hbc%d: %w", version, err)
		}
	}
	return nil
}

func generateOne(src, outDir string, version uint32) error {
	raw, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	var data dataFile
	if err := json.Unmarshal(raw, &data); err != nil {
		return fmt.Errorf("parsing %s: %w", src, err)
	}
	if data.Version != version {
		return fmt.Errorf("%s declares version %d, expected %d", src, data.Version, version)
	}
	if len(data.Instructions) == 0 {
		return fmt.Errorf("%s has no instructions", src)
	}

	var buf bytes.Buffer
	fmt.Fprintf(&buf, `// Code generated by internal/hermes/opcodes/gen from data/hbc%d.json; DO NOT EDIT.
//
// Opcode data derived from %s. The vendored source data and the
// corrections applied to it are documented in data/build_data.py.

package hbc%d

import "github.com/destruct/destruct/internal/hermes/opcodes"

// Table is the Hermes bytecode v%d instruction table.
var Table = opcodes.NewTable(%d, []*opcodes.Opcode{
`, version, data.Source, version, version, version)

	for i, instr := range data.Instructions {
		if instr.Opcode != i {
			return fmt.Errorf("instruction %q declares opcode %d, expected %d (instructions must be listed in opcode order)",
				instr.Name, instr.Opcode, i)
		}

		var fields []string
		fields = append(fields, fmt.Sprintf("Name: %q", instr.Name))
		if len(instr.Operands) > 0 {
			var operands []string
			for _, o := range instr.Operands {
				operandType, err := opcodes.ParseOperandType(o.Type)
				if err != nil {
					return fmt.Errorf("instruction %q: %w", instr.Name, err)
				}
				operand := fmt.Sprintf("{Type: opcodes.%s", operandType)
				switch o.Meaning {
				case "":
				case "string_id":
					operand += ", Meaning: opcodes.MeaningStringID"
				case "function_id":
					operand += ", Meaning: opcodes.MeaningFunctionID"
				case "bigint_id":
					operand += ", Meaning: opcodes.MeaningBigIntID"
				default:
					return fmt.Errorf("instruction %q: unknown meaning %q", instr.Name, o.Meaning)
				}
				operand += "}"
				operands = append(operands, operand)
			}
			fields = append(fields, "Operands: []opcodes.Operand{"+strings.Join(operands, ", ")+"}")
		}
		if instr.RetTarget {
			fields = append(fields, "HasRetTarget: true")
		}

		// Keep multi-line for instructions with operands so the file stays
		// grep-able; one instruction per line is fine either way.
		comment := ""
		if instr.Corrected {
			comment = " // Corrected against the Hermes source (see build_data.py)."
		}
		fmt.Fprintf(&buf, "\t{%s},%s\n", strings.Join(fields, ", "), comment)
	}
	buf.WriteString("})\n")

	if len(data.Builtins) > 0 {
		buf.WriteString(`
// Builtins lists the builtin callable names for this bytecode version,
// indexed by the builtin operand of CallBuiltin / GetBuiltinClosure.
// See data/build_builtins.py for provenance; the list comes from the
// Hermes Builtins.def at the release tag recorded there.
var Builtins = []string{
`)
		for _, name := range data.Builtins {
			fmt.Fprintf(&buf, "\t%q,\n", name)
		}
		buf.WriteString("}\n")
	}

	dir := filepath.Join(outDir, fmt.Sprintf("hbc%d", version))
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	dst := filepath.Join(dir, "opcodes.go")
	return os.WriteFile(dst, buf.Bytes(), 0o644)
}
